function mean(a){ return a.reduce(function(s,x){return s+x;},0)/a.length; }
function covSample(x, y){ if(x.length!==y.length||x.length<2) return NaN; var mx=mean(x), my=mean(y); var s=0; for(var i=0;i<x.length;i++) s+=(x[i]-mx)*(y[i]-my); return s/(x.length-1); }
function covPop(x, y){ if(x.length!==y.length||x.length<1) return NaN; var mx=mean(x), my=mean(y); var s=0; for(var i=0;i<x.length;i++) s+=(x[i]-mx)*(y[i]-my); return s/x.length; }
var EXPORTS = { covSample:covSample, covPop:covPop, mean:mean };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CovarianceForgePure = EXPORTS; }
